/**
 * DELETE /api/v3/tags — delete every tag of the workspace that no response carries.
 * Same authorization as deleting a single tag; answers how many tags were removed.
 */
export const DELETE = withV3ApiWrapper({
  auth: "session",
  action: "deleted",
  targetType: "tag",
  schemas: { query: ZV3TagListQuery },
  handler: async ({ authentication, parsedInput, auditLog, requestId, instance }) =>
    deleteUnusedV3Tags({
      authentication,
      workspaceId: parsedInput.query.workspaceId,
      auditLog,
      requestId,
      instance,
    }),
});
EOF
